// Filter and standardize feed items for Indian tech & remote applicants
const response = $input.first().json;
const jobs = response.jobs || [];
const filtered = [];

for (const j of jobs) {
  const location = (j.candidate_required_location || '').toLowerCase();
  if (!location || location.includes('anywhere') || location.includes('world') || location.includes('india') || location.includes('apac')) {
    filtered.push({
      json: {
        raw_id: j.id,
        title: j.title,
        company: j.company_name,
        source_url: j.url,
        source_name: 'Open Remote Tech Syndicate',
        raw_content: `${j.title} at ${j.company_name}. Location: ${j.candidate_required_location || 'Remote'}. Job Type: ${j.job_type}. Salary: ${j.salary || 'Not Disclosed'}. Description: ${(j.description || '').slice(0, 1500)}`
      }
    });
  }
}

return filtered;

// Parse Gemini extracted JSON and prepare ingestion payload
const raw = $input.first().json;
let parsed = {};

try {
  const text = raw.candidates[0].content.parts[0].text;
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    title: $('Filter Eligible Candidate Roles').first().json.title,
    company_name: $('Filter Eligible Candidate Roles').first().json.company,
    salary_text: 'Not Disclosed',
    official_apply_url: $('Filter Eligible Candidate Roles').first().json.source_url
  };
}

return [{
  json: {
    source_name: $('Filter Eligible Candidate Roles').first().json.source_name,
    source_url: $('Filter Eligible Candidate Roles').first().json.source_url,
    raw_title: $('Filter Eligible Candidate Roles').first().json.title,
    raw_company: $('Filter Eligible Candidate Roles').first().json.company,
    raw_content: $('Filter Eligible Candidate Roles').first().json.raw_content,
    extracted_data: parsed
  }
}];
